<script setup lang="ts">
const props = defineProps<{ endpoint: string; label: string }>(); const emit = defineEmits(['unlocked']); const password = ref(''); const error = ref(''); const busy = ref(false)
async function unlock() { busy.value = true; error.value = ''; try { await $fetch(props.endpoint, { method:'POST',body:{password:password.value} }); emit('unlocked') } catch(e:any) { error.value = e.data?.statusMessage || 'Could not unlock.' } finally { busy.value = false } }
</script>
<template><main class="narrow"><section class="panel"><div class="eyebrow">PASSWORD REQUIRED</div><h1 class="medium">This {{ label }} is password protected.</h1><p>Enter the password shared by your facilitator.</p><form @submit.prevent="unlock"><label>Password<input v-model="password" required type="password" autocomplete="current-password" maxlength="200"></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="button" :disabled="busy">{{ busy ? 'Unlocking…' : 'Unlock' }}</button></form></section></main></template>
